=`umask -S 2\u003e/dev/null \u0026 umask 2\u003e/dev/null`","if [ \"$umaskvalue\" ]; then","  echo -e \"\\e[00;31m[-] Current umask value:\\e[00m\\n$umaskvalue\" ","  echo -e \"\\n\"","fi","","#umask value as in /etc/login.defs","umaskdef=`grep -i \"^UMASK\" /etc/login.defs 2\u003e/dev/null`","if [ \"$umaskdef\" ]; then","  echo -e \"\\e[00;31m[-] umask value as specified in /etc/login.defs:\\e[00m\\n$umaskdef\" ","  echo -e \"\\n\"","fi","","#password policy information as stored in /etc/login.defs","logindefs=`grep \"^PASS_MAX_DAYS\\|^PASS_MIN_DAYS\\|^PASS_WARN_AGE\\|^ENCRYPT_METHOD\" /etc/login.defs 2\u003e/dev/null`","if [ \"$logindefs\" ]; then","  echo -e \"\\e[00;31m[-] Password and storage information:\\e[00m\\n$logindefs\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$logindefs\" ]; then","  mkdir $format/etc-export/ 2\u003e/dev/null","  cp /etc/login.defs $format/etc-export/login.defs 2\u003e/dev/null","fi","}","","job_info()","{","echo -e \"\\e[00;33m### JOBS/TASKS ##########################################\\e[00m\" ","","#are there any cron jobs configured","cronjobs=`ls -la /etc/cron* 2\u003e/dev/null`","if [ \"$cronjobs\" ]; then","  echo -e \"\\e[00;31m[-] Cron jobs:\\e[00m\\n$cronjobs\" ","  echo -e \"\\n\"","fi","","#can we manipulate these jobs in any way","cronjobwwperms=`find /etc/cron* -perm -0002 -type f -exec ls -la {} \\; -exec cat {} 2\u003e/dev/null \\;`","if [ \"$cronjobwwperms\" ]; then","  echo -e \"\\e[00;33m[+] World-writable cron jobs and file contents:\\e[00m\\n$cronjobwwperms\" ","  echo -e \"\\n\"","fi","","#contab contents","crontabvalue=`cat /etc/crontab 2\u003e/dev/null`","if [ \"$crontabvalue\" ]; then","  echo -e \"\\e[00;31m[-] Crontab contents:\\e[00m\\n$crontabvalue\" ","  echo -e \"\\n\"","fi","","crontabvar=`ls -la /var/spool/cron/crontabs 2\u003e/dev/null`","if [ \"$crontabvar\" ]; then","  echo -e \"\\e[00;31m[-] Anything interesting in /var/spool/cron/crontabs:\\e[00m\\n$crontabvar\" ","  echo -e 