pinfo\" ]; then","  echo -e \"\\e[00;31m[-] ARP history:\\e[00m\\n$arpinfo\" ","  echo -e \"\\n\"","fi","","arpinfoip=`ip n 2\u003e/dev/null`","if [ ! \"$arpinfo\" ] \u0026\u0026 [ \"$arpinfoip\" ]; then","  echo -e \"\\e[00;31m[-] ARP history:\\e[00m\\n$arpinfoip\" ","  echo -e \"\\n\"","fi","","#dns settings","nsinfo=`grep \"nameserver\" /etc/resolv.conf 2\u003e/dev/null`","if [ \"$nsinfo\" ]; then","  echo -e \"\\e[00;31m[-] Nameserver(s):\\e[00m\\n$nsinfo\" ","  echo -e \"\\n\"","fi","","nsinfosysd=`systemd-resolve --status 2\u003e/dev/null`","if [ \"$nsinfosysd\" ]; then","  echo -e \"\\e[00;31m[-] Nameserver(s):\\e[00m\\n$nsinfosysd\" ","  echo -e \"\\n\"","fi","","#default route configuration","defroute=`route 2\u003e/dev/null | grep default`","if [ \"$defroute\" ]; then","  echo -e \"\\e[00;31m[-] Default route:\\e[00m\\n$defroute\" ","  echo -e \"\\n\"","fi","","#default route configuration","defrouteip=`ip r 2\u003e/dev/null | grep default`","if [ ! \"$defroute\" ] \u0026\u0026 [ \"$defrouteip\" ]; then","  echo -e \"\\e[00;31m[-] Default route:\\e[00m\\n$defrouteip\" ","  echo -e \"\\n\"","fi","","#listening TCP","tcpservs=`netstat -ntpl 2\u003e/dev/null`","if [ \"$tcpservs\" ]; then","  echo -e \"\\e[00;31m[-] Listening TCP:\\e[00m\\n$tcpservs\" ","  echo -e \"\\n\"","fi","","tcpservsip=`ss -t -l -n 2\u003e/dev/null`","if [ ! \"$tcpservs\" ] \u0026\u0026 [ \"$tcpservsip\" ]; then","  echo -e \"\\e[00;31m[-] Listening TCP:\\e[00m\\n$tcpservsip\" ","  echo -e \"\\n\"","fi","","#listening UDP","udpservs=`netstat -nupl 2\u003e/dev/null`","if [ \"$udpservs\" ]; then","  echo -e \"\\e[00;31m[-] Listening UDP:\\e[00m\\n$udpservs\" ","  echo -e \"\\n\"","fi","","udpservsip=`ss -u -l -n 2\u003e/dev/null`","if [ ! \"$udpservs\" ] \u0026\u0026 [ \"$udpservsip\" ]; then","  echo -e \"\\e[00;31m[-] Listening UDP:\\e[00m\\n$udpservsip\" ","  echo -e \"\\n\"","fi","}","","services_info()","{","echo -e \"\\e[00;33m### SERVICES #############################################\\e[00m\" ","","#running processes","psaux=`ps aux 2\u003e/dev/null`","if [ \"$psaux\" ]; then","  echo -e \"\\e[00;31m[-] Running processes:\\e[00m\\n$psaux\" ","  echo -e \"\\n\"","fi","","#lookup process binary path and permissisons","procperm=`ps aux 2\u003e/dev/null | awk '{print $11}'|xargs -r ls -la 2\u003e/dev/null |awk '!x[$0]++' 2\u003e/dev/null`","if [ \"$procperm\" ]; then","  echo -e \"\\e[00;31m[-] Process binaries and associated permissions (from above list):\\e[00m\\n$procperm\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$procperm\" ]; then","procpermbase=`ps aux 2\u003e/dev/null | awk '{print $11}' | xargs -r ls 2\u003e/dev/null | awk '!x[$0]++' 2\u003e/dev/null`","  mkdir $format/ps-export/ 2\u003e/dev/null","  for i in $procpermbase; do cp --parents $i $format/ps-export/; done 2\u003e/dev/null","fi","","#anything 'useful' in inetd.conf","inetdread=`cat /etc/inetd.conf 2\u003e/dev/null`","if [ \"$inetdread\" ]; then","  echo -e \"\\e[00;31m[-] Contents of /etc/inetd.conf:\\e[00m\\n$inetdread\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$inetdread\" ]; then","  mkdir $format/etc-export/ 2\u003e/dev/null","  cp /etc/inetd.conf $format/etc-export/inetd.conf 2\u003e/dev/null","fi","","#very 'rough' command to extract associated binaries from inetd.conf \u0026 show permisisons of each","inetdbinperms=`awk '{print $7}' /etc/inetd.conf 2\u003e/dev/null |xargs -r ls -la 2\u003e/dev/null`","if [ \"$inetdbinperms\" ]; then","  echo -e \"\\e[00;31m[-] The related inetd binary permissions:\\e[00m\\n$inetdbinperms\" ","  echo -e \"\\n\"","fi","","xinetdread=`cat /etc/xinetd.conf 2\u003e/dev/null`","if [ \"$xinetdread\" ]; then","  echo -e \"\\e[00;31m[-] Contents of /etc/xinetd.conf:\\e[00m\\n$xinetdread\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$xinetdread\" ]; then","  mkdir $format/etc-export/ 2\u003e/dev/null","  cp /etc/xinetd.conf $format/etc-export/xinetd.conf 2\u003e/dev/null","fi","","xinetdincd=`grep \"/etc/xinetd.d\" /etc/xinetd.conf 2\u003e/dev/null`","if [ \"$xinetdincd\" ]; then","  echo -e \"\\e[00;31m[-] /etc/xinetd.d is included in /etc/xinetd.conf - associated binary permissions are listed below:\\e[00m\"; ls -la /etc/xinetd.d 2\u003e/dev/null ","  echo -e \"\\n\"","fi","","#very 'rough' command to extract associated binaries from xinetd.conf \u0026 show permisisons of each","xinetdbinperms=`awk '{print $7}' /etc/xinetd.conf 2\u003e/dev/null |xargs -r ls -la 2\u003e/dev/null`","if [ \"$xinetdbinperms\" ]; then","  echo -e \"\\e[00;31m[-] The related xinetd binary permissions:\\e[00m\\n$xinetdbinperms\" ","  echo -e \"\\n\"","fi","","initdread=`ls -la /etc/init.d 2\u003e/dev/null`","if [ \"$initdread\" ]; then","  echo -e \"\\e[00;31m[-] /etc/init.d/ binary permissions:\\e[00m\\n$initdread\" ","  echo -e \"\\n\"","fi","","#init.d files NOT belonging to root!","initdperms=`find /etc/init.d/ \\! -uid 0 -type f 2\u003e/dev/null |xargs -r ls -la 2\u003e/dev/null`","if [ \"$initdperms\" ]; then","  echo -e \"\\e[00;31m[-] /etc/init.d/ files not belonging to root:\\e[00m\\n$initdperms\" ","  echo -e \"\\n\"","fi","","rcdread=`ls -la /etc/rc.d/init.d 2\u003e/dev/null`","if [ \"$rcdread\" ]; then","  echo -e \"\\e[00;31m[-] /etc/rc.d/init.d binary permissions:\\e[00m\\n$rcdread\" ","  echo -e \"\\n\"","fi","","#init.d files NOT belonging to root!","rcdperms=`find /etc/rc.d/init.d \\! -uid 0 -type f 2\u003e/dev/null |xargs -r ls -la 2\u003e/dev/null`","if [ \"$rcdperms\" ]; then","  echo -e \"\\e[00;31m[-] /etc/rc.d/init.d files not belonging to root:\\e[00m\\n$rcdperms\" ","  echo -e \"\\n\"","fi","","usrrcdread=`ls -la /usr/local/etc/rc.d 2\u003e/dev/null`","if [ \"$usrrcdread\" ]; then","  echo -e \"\\e[00;31m[-] /usr/local/etc/rc.d binary permissions:\\e[00m\\n$usrrcdread\" ","  echo -e \"\\n\"","fi","","#rc.d files NOT belonging to root!","usrrcdperms=`find /usr/local/etc/rc.d \\! -uid 0 -type f 2\u003e/dev/null |xargs -r ls -la 2\u0