 service with default root/root credentials!\\e[00m\\n$mysqlconnect\" ","  echo -e \"\\n\"","fi","","#mysql version details","mysqlconnectnopass=`mysqladmin -uroot version 2\u003e/dev/null`","if [ \"$mysqlconnectnopass\" ]; then","  echo -e \"\\e[00;33m[+] We can connect to the local MYSQL service as 'root' and without a password!\\e[00m\\n$mysqlconnectnopass\" ","  echo -e \"\\n\"","fi","","#postgres details - if installed","postgver=`psql -V 2\u003e/dev/null`","if [ \"$postgver\" ]; then","  echo -e \"\\e[00;31m[-] Postgres version:\\e[00m\\n$postgver\" ","  echo -e \"\\n\"","fi","","#checks to see if any postgres password exists and connects to DB 'template0' - following commands are a variant on this","postcon1=`psql -U postgres -w template0 -c 'select version()' 2\u003e/dev/null | grep version`","if [ \"$postcon1\" ]; then","  echo -e \"\\e[00;33m[+] We can connect to Postgres DB 'template0' as user 'postgres' with no password!:\\e[00m\\n$postcon1\" ","  echo -e \"\\n\"","fi","","postcon11=`psql -U postgres -w template1 -c 'select version()' 2\u003e/dev/null | grep version`","if [ \"$postcon11\" ]; then","  echo -e \"\\e[00;33m[+] We can connect to Postgres DB 'template1' as user 'postgres' with no password!:\\e[00m\\n$postcon11\" ","  echo -e \"\\n\"","fi","","postcon2=`psql -U pgsql -w template0 -c 'select version()' 2\u003e/dev/null | grep version`","if [ \"$postcon2\" ]; then","  echo -e \"\\e[00;33m[+] We can connect to Postgres DB 'template0' as user 'psql' with no password!:\\e[00m\\n$postcon2\" ","  echo -e \"\\n\"","fi","","postcon22=`psql -U pgsql -w template1 -c 'select version()' 2\u003e/dev/null | grep version`","if [ \"$postcon22\" ]; then","  echo -e \"\\e[00;33m[+] We can connect to Postgres DB 'template1' as user 'psql' with no password!:\\e[00m\\n$postcon22\" ","  echo -e \"\\n\"","fi","","#apache details - if installed","apachever=`apache2 -v 2\u003e/dev/null; httpd -v 2\u003e/dev/null`","if [ \"$apachever\" ]; then","  echo -e \"\\e[00;31m[-] Apache version:\\e[00m\\n$apachever\" ","  echo -e \"\\n\"","fi","","#what account is apache running under","apacheusr=`grep -i 'user\\|group' /etc/apache2/envvars 2\u003e/dev/null |awk '{sub(/.*\\export /,\"\")}1' 2\u003e/dev/null`","if [ \"$apacheusr\" ]; then","  echo -e \"\\e[00;31m[-] Apache user configuration:\\e[00m\\n$apacheusr\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$apacheusr\" ]; then","  mkdir --parents $format/etc-export/apache2/ 2\u003e/dev/null","  cp /etc/apache2/envvars $format/etc-export/apache2/envvars 2\u003e/dev/null","fi","","#installed apache modules","apachemodules=`apache2ctl -M 2\u003e/dev/null; httpd -M 2\u003e/dev/null`","if [ \"$apachemodules\" ]; then","  echo -e \"\\e[00;31m[-] Installed Apache modules:\\e[00m\\n$apachemodules\" ","  echo -e \"\\n\"","fi","","#htpasswd check","htpasswd=`find / -name .htpasswd -print -exec cat {} \\; 2\u003e/dev/null`","if [ \"$htpasswd\" ]; then","    echo -e \"\\e[00;33m[-] htpasswd found - could contain passwords:\\e[00m\\n$htpasswd\"","    echo -e \"\\n\"","fi","","#anything in the default http home dirs (a thorough only check as output can be large)","if [ \"$thorough\" = \"1\" ]; then","  apachehomedirs=`ls -alhR /var/www/ 2\u003e/dev/null; ls -alhR /srv/www/htdocs/ 2\u003e/dev/null; ls -alhR /usr/local/www/apache2/data/ 2\u003e/dev/null; ls -alhR /opt/lampp/htdocs/ 2\u003e/dev/null`","  if [ \"$apachehomedirs\" ]; then","    echo -e \"\\e[00;31m[-] www home dir contents:\\e[00m\\n$apachehomedirs\" ","    echo -e \"\\n\"","  fi","fi","","}","","interesting_files()","{","echo -e \"\\e[00;33m### INTERESTING FILES ####################################\\e[00m\" ","","#checks to see if various files are installed","echo -e \"\\e[00;31m[-] Useful file locations:\\e[00m\" ; which nc 2\u003e/dev/null ; which netcat 2\u003e/dev/null ; which wget 2\u003e/dev/null ; which nmap 2\u003e/dev/null ; which gcc 2\u003e/dev/null; which curl 2\u003e/dev/null ","echo -e \"\\n\" ","","#limited search for installed compilers","compiler=`dpkg --list 2\u003e/dev/null| grep compiler |grep -v decompiler 2\u003e/dev/null \u0026\u0026 yum list installed 'gcc*' 2\u003e/dev/null| grep gcc 2\u003e/dev/null`","if [ \"$compiler\" ]; then","  echo -e \"\\e[00;31m[-] Installed compilers:\\e[00m\\n$compiler\" ","  echo -e \"\\n\"","fi","","#manual check - lists out sensitive files, can we read/modify etc.","echo -e \"\\e[00;31m[-] Can we read/write sensitive files:\\e[00m\" ; ls -la /etc/passwd 2\u003e/dev/null ; ls -la /etc/group 2\u003e/dev/null ; ls -la /etc/profile 2\u003e/dev/null; ls -la /etc/shadow 2\u003e/dev/null ; ls -la /etc/master.passwd 2\u003e/dev/null ","echo -e \"\\n\" ","","#search for suid files","allsuid=`find / -perm -4000 -type f 2\u003e/dev/null`","findsuid=`find $allsuid -perm -4000 -type f -exec ls -la {} 2\u003e/dev/null \\;`","if [ \"$findsuid\" ]; then","  echo -e \"\\e[00;31m[-] SUID files:\\e[00m\\n$findsuid\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$findsuid\" ]; then","  mkdir $format/suid-files/ 2\u003e/dev/null","  for i in $findsuid; do cp $i $format/suid-files/; done 2\u003e/dev/null","fi","","#list of 'interesting' suid files - feel free to make additions","intsuid=`find $allsuid -perm -4000 -type f -exec ls -la {} \\; 2\u003e/dev/null | grep -w $binarylist 2\u003e/dev/null`","if [ \"$intsuid\" ]; then","  echo -e \"\\e[00;33m[+] Possibly interesting SUID files:\\e[00m\\n$intsuid\" ","  echo -e \"\\n\"","fi","","#lists world-writable suid files","wwsuid=`find $allsuid -perm -4002 -type f -exec ls -la {} 2\u003e/dev/null \\;`","if [ \"$wwsuid\" ]; then","  echo -e \"\\e[00;33m[+] World-writable SUID files:\\e[00m\\n$wwsuid\" ","  echo -e \"\\n\"","fi","","#lists world-writable suid files owned by root","wwsuidrt=`find $allsuid -uid 0 -perm -4002 -type f -exec ls -la {} 2\u003e/dev/null \\;`","if [ \"$wwsuidrt\" ]; then","  echo -e \"\\e[00;33m[+] World-writable SUID files owned by root:\\e[00m\\n$wwsuidrt\" ","  echo -e \"\\n\"","fi","","#search for sgid files","allsgid=`find / -perm -2000 -type f 2\u003e/dev/null`","findsgid=`find $allsgid -perm -2000 -type f -exec ls -la {} 2\u003e/dev/null \\;`","if [ \"$findsgid\" ]; then","  echo -e \"\\e[00;31m[-] SGID files:\\e[00m\\n$findsgid\" ","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$findsgid\" ]; then","  mkdir $format/sgid-files/ 2\u003e/dev/null","  for i in $findsgid; do cp $i $format/sgid-files/; done 2\u003e/dev/null","fi","","#list of 'interesting' sgid files","intsgid=`find $allsgid -perm -2000 -type f  -exec ls -la {} \\; 2\u003e/dev/null | grep -w $binarylist 2\u003e/dev/null`","if [ \"$intsgid\" ]; then","  echo -e \"\\e[00;33m[+] Possibly interesting SGID files:\\e[00m\\n$intsgid\" ","  echo -e \"\\n\"","fi","","#lists world-writable sgid files","wwsgid=`find $allsgid -perm -2002 -type f -exec ls -la {} 2\u003e/dev/null \\;`","if [ \"$wwsgid\" ]; then","  echo -e \"\\e[00;33m[+] World-writable SGID files:\\e[00m\\n$wwsgid\" ","  echo -e \"\\n\"","fi","","#lists world-writable sgid files owned by root","wwsgidrt=`find $allsgid -uid 0 -perm -2002 -type f -exec ls -la {} 2\u003e/dev/null \\;`","if [ \"$wwsgidrt\" ]; then","  echo -e \"\\e[00;33m[+] World-writable SGID files owned by root:\\e[00m\\n$wwsgidrt\" ","  echo -e \"\\n\"","fi","","#list all files with POSIX capabilities set along with there capabilities","fileswithcaps=`getcap -r / 2\u003e/dev/null || /sbin/getcap -r / 2\u003e/dev/null`","if [ \"$fileswithcaps\" ]; then","  echo -e \"\\e[00;31m[+] Files with POSIX capabilities set:\\e[00m\\n$fileswithcaps\"","  echo -e \"\\n\"","fi","","if [ \"$export\" ] \u0026\u0026 [ \"$fileswithcaps\" ]; then","  mkdir $format/files_with_capabilities/ 2\u003e/dev/null","  for i in $fileswithcaps; do cp $i $format/files_with_capabilities/; done 2\u003e/dev/null","fi","","#searches /etc/security/capability.conf for users associated capapilies","userswithcaps=`grep -v '^#\\|none\\|^$' /etc/security/capability.conf 2\u003e/dev/null`","if [ \"$userswithcaps\" ]; then","  echo -e \"\\e[00;33m[+] Users with specific POSIX capabilities:\\e[00m\\n$userswithcaps\"","  echo -e \"\\n\"","fi","","if [ \"$userswithcaps\" ] ; then","#matches the capabilities found associated with users with the current user","matchedcaps=`echo -e \"$userswithcaps\" | grep \\`whoami\\` | awk '{print $1}' 2\u003e/dev/null`","\tif [ \"$matchedcaps\" ]; then","\t\techo -e \"\\e[00;33m[+] Capabilities associated with the current user:\\e[00m\\n$matchedcaps\"","\t\techo -e \"\\n\"","\t\t#matches the files with capapbilities with capabilities associated with the current user","\t\tmatchedfiles=`echo -e \"$matchedcaps\" | while read -r cap ; do echo -e \"$fileswithcaps\" | grep \"$cap\" ; done 2\u003e/dev/null`","\t\tif [ \"$matchedfiles\" ]; then","\t\t\techo -e \"\\e[00;33m[+] Files with the same capabilities associated with the current user (You may want to try abusing those capabilties):\\e[00m\\n$matchedfiles\"","\t\t\techo -e \"\\n\"","\t\t\t#lists the permissions of the files having the same capabilies associated with the current user","\t\t\tmatchedfilesperms=`echo -e \"$matchedfiles\" | awk '{print $1}' | while read -r f; do ls -la $f ;done 2\u003e/dev/null`","\t\t\techo -e \"\\e[00;33m[+] Permissions of files with the same capabilities associated with the current user:\\e[00m\\n$matchedfilesperms\"","\t\t\techo -e \"\\n\"","\t\t\tif [ \"$matchedfilesperms\" ]; then","\t\t\t\t#checks if any of the files with same capabilities associated with the current user is writable","\t\t\t\twritablematchedfiles=`echo -e \"$matchedfiles\" | awk '{print $1}' | while read -r f; do find $f -writable -exec ls -la {} + ;done 2\u003e/dev/null`","\t\t\t\tif [ \"$writablematchedfiles\" ]; then","\t\t\t\t\techo -e \"\\e[00;33m[+] User/Group writable files with the same capabilities associated with the current user:\\e[00m\\n$writablematchedfiles\"","\t\t\t\t\techo -e \"\\n\"","\t\t\t\tfi","\t\t\tfi","\